 * @param {string[]} existingNumbers - Array of invoice numbers already used
 * @returns {import('./result.js').Result}
 */
export function issueInvoice(invoice, existingNumbers) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    ...invoice,
    number,
    status: 'issued',
  });
}

/**
 * Apply a voucher to an invoice.
 * @param {any} invoice
 * @param {{ code: string, amount: number }} voucher
 * @returns {import('./result.js').Result}
 */
export function applyVoucher(invoice, { code, amount }) {
  // Validate invoice is draft
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  // Check if invoice already has a voucher
  if (invoice.voucher) {
    return fail('VOUCHER_EXISTS');
  }

  // Validate amount
  if (!Number.isInteger(amount) || amount <= 0) {
    return fail('AMOUNT_INVALID');
  }

  return ok({
    ...invoice,
    voucher: { code, amount },
  });
}

