  // Subtotal: 2000
  // Discount: 200
  // After discount: 1800
  // VAT: 1800 * 0.21 = 378
  // Total: 2000 - 200 + 378 = 2178
  assert.deepStrictEqual(totals, {
    subtotal: 2000,
    discount: 200,
    vat: 378,
    total: 2178,
  });
});

