  const totals = invoiceTotals(invoice);
  // Line 1: 2000 - 200 + (1800 * 0.21 = 378) = 2178
  // Line 2: 6000 - 0 + (6000 * 0.09 = 540) = 6540
  // Subtotal: 8000, Discount: 200, VAT: 378 + 540 = 918
