    vat: 420,
    total: 2420,
  });
});

test('invoiceTotals with multiple VAT rates', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 1000, vatRate: 0 },
      { qty: 1, unitPrice: 1000, vatRate: 9 },
      { qty: 1, unitPrice: 1000, vatRate: 21 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Subtotal: 3000
  // VAT: 0 + 90 + 210 = 300
  assert.deepStrictEqual(totals, {
    subtotal: 3000,
    discount: 0,
    vat: 300,
    total: 3300,
  });
});

