  invoice.status = 'sent';

  const result = addLine(invoice, { sku: 'DEV-HOUR', qty: 1 });

  assert.strictEqual(result.ok, false);
  assert.strictEqual(result.error, 'NOT_DRAFT');
});

test('addLine does not mutate invoice', () => {
