    lines: [
      { qty: 2, unitPrice: 1000, discountPercent: 10, vatRate: 21 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Subtotal: 2000
  // Discount: 200
  // After discount: 1800
  // VAT: 1800 * 0.21 = 378
  // Total: 2000 - 200 + 378 = 2178
