    issueDate: '2025-12-15',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });

  assert.ok(result.ok);
  assert.strictEqual(result.value.customerId, 'C-001');
});

test('createInvoice still rejects non-existent normalized customer id', () => {
  const result = createInvoice({
    customerId: 'c-999',
    issueDate: '2025-12-15',
