test('issueInvoice preserves terms and dueDate', () => {
  const created = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });

  assert.ok(created.ok);
  const issued = issueInvoice(created.value, []);
  assert.ok(issued.ok);
  assert.strictEqual(issued.value.terms, 'NET14');
  assert.strictEqual(issued.value.dueDate, '2025-12-29');
});

test('invoiceTotals includes voucher field', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });

  assert.ok(invoice.ok);
  const totals = invoiceTotals(invoice.value);
  assert.ok('voucher' in totals);
  assert.strictEqual(totals.voucher, 0);
});

test('invoiceTotals with voucher subtracts from total', () => {
  const created = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  assert.ok(created.ok);
  const withVoucher = applyVoucher(created.value, { code: 'SAVE10', amount: 1000 });
  assert.ok(withVoucher.ok);

  const totalsWithout = invoiceTotals(created.value);
  const totalsWith = invoiceTotals(withVoucher.value);

  assert.strictEqual(totalsWith.voucher, 1000);
  assert.strictEqual(totalsWith.total, totalsWithout.total - 1000);
});

test('applyVoucher adds voucher to draft invoice', () => {
  const created = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  assert.ok(created.ok);
  const result = applyVoucher(created.value, { code: 'PROMO', amount: 5000 });
  assert.ok(result.ok);
  assert.deepStrictEqual(result.value.voucher, { code: 'PROMO', amount: 5000 });
});

test('applyVoucher fails on non-draft invoice', () => {
  const created = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  assert.ok(created.ok);
  const issued = issueInvoice(created.value, []);
  assert.ok(issued.ok);

  const result = applyVoucher(issued.value, { code: 'PROMO', amount: 1000 });
  assert.ok(!result.ok);
  assert.strictEqual(result.error, 'NOT_DRAFT');
});

test('applyVoucher fails if voucher already exists', () => {
  const created = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  assert.ok(created.ok);
  const withVoucher = applyVoucher(created.value, { code: 'PROMO1', amount: 1000 });
  assert.ok(withVoucher.ok);

  const result = applyVoucher(withVoucher.value, { code: 'PROMO2', amount: 2000 });
  assert.ok(!result.ok);
  assert.strictEqual(result.error, 'VOUCHER_EXISTS');
});

test('applyVoucher fails with non-integer amount', () => {
  const created = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  assert.ok(created.ok);
  const result = applyVoucher(created.value, { code: 'PROMO', amount: 50.5 });
  assert.ok(!result.ok);
  assert.strictEqual(result.error, 'AMOUNT_INVALID');
});

test('applyVoucher fails with zero amount', () => {
  const created = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  assert.ok(created.ok);
  const result = applyVoucher(created.value, { code: 'PROMO', amount: 0 });
  assert.ok(!result.ok);
  assert.strictEqual(result.error, 'AMOUNT_INVALID');
});

test('applyVoucher fails with negative amount', () => {
  const created = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  assert.ok(created.ok);
  const result = applyVoucher(created.value, { code: 'PROMO', amount: -1000 });
  assert.ok(!result.ok);
  assert.strictEqual(result.error, 'AMOUNT_INVALID');
});

test('applyVoucher preserves invoice properties', () => {
  const created = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });

  assert.ok(created.ok);
  const result = applyVoucher(created.value, { code: 'PROMO', amount: 1000 });
  assert.ok(result.ok);

  assert.strictEqual(result.value.customerId, created.value.customerId);
  assert.strictEqual(result.value.issueDate, created.value.issueDate);
  assert.strictEqual(result.value.status, created.value.status);
  assert.deepStrictEqual(result.value.lines, created.value.lines);
});

test('invoiceTotals with voucher larger than subtotal+vat still clamps to zero', () => {
  const created = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [{ sku: 'STICKER', qty: 1 }],
  });

  assert.ok(created.ok);
  const totalsWithout = invoiceTotals(created.value);
  const voucherAmount = totalsWithout.total + 10000;

  const withVoucher = applyVoucher(created.value, { code: 'HUGE', amount: voucherAmount });
  assert.ok(withVoucher.ok);

  const totalsWith = invoiceTotals(withVoucher.value);
  assert.strictEqual(totalsWith.total, 0);
});

