import test from 'node:test';
import assert from 'node:assert';
import { createInvoice, lineTotal, lineDiscount, lineVat, invoiceTotals, addLine, removeLine, issueInvoice, applyVoucher } from '../src/invoices.js';

test('createInvoice with valid inputs', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DEV-HOUR', qty: 1 },
    ],
  });

  assert.strictEqual(result.ok, true);
  assert.strictEqual(result.value.customerId, 'C-001');
  assert.strictEqual(result.value.issueDate, '2025-12-15');
  assert.strictEqual(result.value.status, 'draft');
  assert.strictEqual(result.value.lines.length, 2);

  assert.strictEqual(result.value.lines[0].sku, 'DES-HOUR');
  assert.strictEqual(result.value.lines[0].qty, 2);
  assert.strictEqual(result.value.lines[0].name, 'Design work (hour)');
  assert.strictEqual(result.value.lines[0].unitPrice, 8500);
  assert.strictEqual(result.value.lines[0].vatRate, 21);

  assert.strictEqual(result.value.lines[1].sku, 'DEV-HOUR');
  assert.strictEqual(result.value.lines[1].qty, 1);
  assert.strictEqual(result.value.lines[1].name, 'Development (hour)');
  assert.strictEqual(result.value.lines[1].unitPrice, 9500);
  assert.strictEqual(result.value.lines[1].vatRate, 21);
});

test('createInvoice with unknown customer', () => {
  const result = createInvoice({
    customerId: 'unknown-id',
    issueDate: '2025-12-15',
    lines: [{ sku: 'SKU-A', qty: 1 }],
  });

  assert.strictEqual(result.ok, false);
  assert.strictEqual(result.error, 'CUSTOMER_NOT_FOUND');
});

test('createInvoice with invalid date format', () => {
  const cases = [
    '2025-13-15',  // invalid month
    '2025-12-32',  // invalid day
    '2025-02-30',  // Feb 30th
    '12/15/2025',  // wrong format
    '2025/12/15',  // wrong format
    '15-12-2025',  // wrong format
    '2025-1-15',   // missing leading zero
    '2025-12-5',   // missing leading zero
    '',            // empty
    '2025',        // incomplete
  ];

  for (const date of cases) {
    const result = createInvoice({
      customerId: '1',
      issueDate: date,
      lines: [{ sku: 'SKU-A', qty: 1 }],
    });

    assert.strictEqual(result.ok, false, `Should fail for date: ${date}`);
    assert.strictEqual(result.error, 'DATE_INVALID', `Should return DATE_INVALID for: ${date}`);
  }
});

test('createInvoice with no lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [],
  });

  assert.strictEqual(result.ok, false);
  assert.strictEqual(result.error, 'NO_LINES');
});

test('createInvoice with no lines array', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: null,
  });

  assert.strictEqual(result.ok, false);
  assert.strictEqual(result.error, 'NO_LINES');
});

test('createInvoice with invalid quantities', () => {
  const cases = [
    { qty: 0, reason: 'zero' },
    { qty: -1, reason: 'negative' },
    { qty: 1.5, reason: 'decimal' },
    { qty: -0.5, reason: 'negative decimal' },
    { qty: Infinity, reason: 'infinity' },
  ];

  for (const { qty, reason } of cases) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty }],
    });

    assert.strictEqual(result.ok, false, `Should fail for qty: ${reason}`);
    assert.strictEqual(result.error, 'QTY_INVALID', `Should return QTY_INVALID for: ${reason}`);
  }
});

test('createInvoice with unknown SKU', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [{ sku: 'UNKNOWN-SKU', qty: 1 }],
  });

  assert.strictEqual(result.ok, false);
  assert.strictEqual(result.error, 'UNKNOWN_SKU');
});

test('createInvoice does not mutate input', () => {
  const lines = [{ sku: 'DES-HOUR', qty: 2 }];
  const linesCopy = JSON.parse(JSON.stringify(lines));

  createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines,
  });

  assert.deepStrictEqual(lines, linesCopy);
});

test('createInvoice with valid edge case dates', () => {
  const validDates = [
    '2025-01-01',
    '2025-12-31',
    '2000-02-29',  // leap year
    '1900-01-01',
    '9999-12-31',
  ];

  for (const date of validDates) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: date,
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    });

    assert.strictEqual(result.ok, true, `Should succeed for valid date: ${date}`);
  }
});

test('lineTotal calculates qty times unitPrice', () => {
  const line = { qty: 5, unitPrice: 2000 };
  assert.strictEqual(lineTotal(line), 10000);
});

test('lineTotal with qty 1', () => {
  const line = { qty: 1, unitPrice: 8500 };
  assert.strictEqual(lineTotal(line), 8500);
});

test('lineTotal with large qty and price', () => {
  const line = { qty: 100, unitPrice: 120000 };
  assert.strictEqual(lineTotal(line), 12000000);
});

test('lineTotal with single cent price', () => {
  const line = { qty: 3, unitPrice: 50 };
  assert.strictEqual(lineTotal(line), 150);
});

test('invoiceTotals with single line', () => {
  const invoice = {
    lines: [{ qty: 2, unitPrice: 8500 }],
  };
  const result = invoiceTotals(invoice);
  assert.strictEqual(result.subtotal, 17000);
  assert.strictEqual(result.vat, 0);
  assert.strictEqual(result.total, 17000);
});

test('invoiceTotals with multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 2, unitPrice: 8500 },
      { qty: 1, unitPrice: 9500 },
      { qty: 3, unitPrice: 1000 },
    ],
  };
  const result = invoiceTotals(invoice);
  // 2*8500 + 1*9500 + 3*1000 = 17000 + 9500 + 3000 = 29500
  assert.strictEqual(result.subtotal, 29500);
  assert.strictEqual(result.vat, 0);
  assert.strictEqual(result.total, 29500);
});

test('invoiceTotals with empty lines array', () => {
  const invoice = { lines: [] };
  const result = invoiceTotals(invoice);
  assert.strictEqual(result.subtotal, 0);
  assert.strictEqual(result.vat, 0);
  assert.strictEqual(result.total, 0);
});

test('invoiceTotals does not mutate invoice', () => {
  const invoice = {
    lines: [{ qty: 2, unitPrice: 8500 }],
  };
  const invoiceCopy = JSON.parse(JSON.stringify(invoice));

  invoiceTotals(invoice);

  assert.deepStrictEqual(invoice, invoiceCopy);
});

test('invoiceTotals with large amounts', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 120000 },
      { qty: 5, unitPrice: 245000 },
    ],
  };
  const result = invoiceTotals(invoice);
  // 10*120000 + 5*245000 = 1200000 + 1225000 = 2425000
  assert.strictEqual(result.subtotal, 2425000);
  assert.strictEqual(result.vat, 0);
  assert.strictEqual(result.total, 2425000);
});

test('lineTotal does not mutate line', () => {
  const line = { qty: 2, unitPrice: 8500 };
  const lineCopy = JSON.parse(JSON.stringify(line));

  lineTotal(line);

  assert.deepStrictEqual(line, lineCopy);
});

test('addLine adds a new line to invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });

  const result = addLine(invoiceResult.value, { sku: 'DEV-HOUR', qty: 1 });

  assert.strictEqual(result.ok, true);
  assert.strictEqual(result.value.lines.length, 2);
  assert.strictEqual(result.value.lines[1].sku, 'DEV-HOUR');
  assert.strictEqual(result.value.lines[1].qty, 1);
  assert.strictEqual(result.value.lines[1].name, 'Development (hour)');
  assert.strictEqual(result.value.lines[1].unitPrice, 9500);
});

test('addLine increases qty when SKU already exists', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });

  const result = addLine(invoiceResult.value, { sku: 'DES-HOUR', qty: 3 });

  assert.strictEqual(result.ok, true);
  assert.strictEqual(result.value.lines.length, 1);
  assert.strictEqual(result.value.lines[0].sku, 'DES-HOUR');
  assert.strictEqual(result.value.lines[0].qty, 5);
});

test('addLine validates qty', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const cases = [0, -1, 1.5, -0.5, Infinity];

  for (const qty of cases) {
    const result = addLine(invoiceResult.value, { sku: 'DEV-HOUR', qty });
    assert.strictEqual(result.ok, false);
    assert.strictEqual(result.error, 'QTY_INVALID');
  }
});

test('addLine validates SKU', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const result = addLine(invoiceResult.value, { sku: 'UNKNOWN-SKU', qty: 1 });

  assert.strictEqual(result.ok, false);
  assert.strictEqual(result.error, 'UNKNOWN_SKU');
});

test('addLine rejects non-draft invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

